def manifest():
    rows = []
    for d in ("stems", "notes", "previews"):
        for f in sorted(os.listdir(os.path.join(MUSIC, d))):
            if f.endswith(".ogg"): rows.append({"path": f"{d}/{f}", "bytes": os.path.getsize(os.path.join(MUSIC, d, f))})
    return rows
spec["manifest"] = manifest()
json.dump(spec, open(os.path.join(MUSIC, "music-spec.json"), "w"), indent=1)
print("files", len(spec["manifest"]), "MB", round(sum(r["bytes"] for r in spec["manifest"]) / 1e6, 2))
